package com.thangit.boardinghouse.service.integration;

import static com.thangit.boardinghouse.service.integration.IntegrationCenter.*;
import com.thangit.boardinghouse.security.AuthenticatedUser;
import jakarta.validation.constraints.*;
import java.net.*;
import java.net.http.*;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.databind.json.JsonMapper;

/** Explicit owner text input only. No document/identity/tenant retrieval and no write tools. */
@Service
public class AiIntegration {
    public record Request(@NotBlank String purpose,@NotBlank @Size(max=1200) String text,boolean consent){}
    final JdbcClient db;final IntegrationCenter center;final IntegrationVault vault;final JsonMapper json;final TransactionTemplate tx;
    final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).followRedirects(HttpClient.Redirect.NEVER).build();
    public AiIntegration(JdbcClient db,IntegrationCenter center,IntegrationVault vault,JsonMapper json,org.springframework.transaction.PlatformTransactionManager manager){this.db=db;this.center=center;this.vault=vault;this.json=json;tx=new TransactionTemplate(manager);}
    public Object suggest(AuthenticatedUser actor,String key,Request request){long owner=center.owner(actor);if(!Set.of("FAQ","MESSAGE").contains(request.purpose())||!request.consent()||request.text().matches("(?s).*(?:[0-9][\\s.-]*){9,}.*")||request.text().matches("(?is).*[^\\s@]+@[^\\s@]+\\.[^\\s@]+.*")||request.text().matches("(?is).*(?:CCCD|CMND|passport|hộ chiếu|căn cước).*"))throw invalid("AI_EXPLICIT_NON_PERSONAL_INPUT_REQUIRED");if(key==null||!key.matches("[a-zA-Z0-9:_-]{8,100}"))throw invalid("AI_IDEMPOTENCY_REQUIRED");var c=center.config(owner,"AI");if(!c.enabled()||!c.bool(request.purpose().equals("FAQ")?"faqEnabled":"messageSuggestionsEnabled"))throw invalid("AI_FEATURE_DISABLED");String hash=WebPushSender.hash(request.purpose()+"|"+request.text());
        boolean fresh=Boolean.TRUE.equals(tx.execute(status->{db.sql("SELECT id FROM users WHERE id=:id FOR UPDATE").param("id",owner).query(Long.class).single();var old=db.sql("SELECT payload_hash FROM integration_operations WHERE owner_id=:owner AND kind='AI' AND operation='AI_GENERATE' AND request_key=:key").param("owner",owner).param("key",key).query().listOfRows();if(!old.isEmpty()){if(!hash.equals(old.getFirst().get("payload_hash")))throw invalid("AI_IDEMPOTENCY_CONFLICT");return false;}long limit=c.settings().get("monthlyLimit") instanceof Number number?number.longValue():100;if(limit<=0)throw invalid("AI_USAGE_DISABLED");limit=Math.min(limit,10000);var month=LocalDate.now(ZoneOffset.UTC).withDayOfMonth(1).atStartOfDay();if(db.sql("SELECT COUNT(*) FROM integration_operations WHERE owner_id=:owner AND kind='AI' AND operation='AI_GENERATE' AND created_at>=:month").param("owner",owner).param("month",month).query(Long.class).single()>=limit)throw invalid("AI_MONTHLY_LIMIT_REACHED");db.sql("INSERT INTO integration_operations(owner_id,kind,operation,request_key,payload_hash,provider,environment,status,result_code,actor_id,created_at) VALUES(:owner,'AI','AI_GENERATE',:key,:hash,:provider,:environment,'TESTING','AI_REQUEST_CREATED',:owner,:at)").param("owner",owner).param("key",key).param("hash",hash).param("provider",c.provider()).param("environment",c.environment()).param("at",LocalDateTime.now(ZoneOffset.UTC)).update();return true;}));
        if(!fresh)return Map.of("status","ALREADY_PROCESSED","mode",c.provider(),"content","Yêu cầu đã được xử lý. Nội dung không lưu trong nhật ký; không gọi lại provider cho cùng khóa.");
        String state="ERROR",code="AI_PROVIDER_REQUEST_FAILED",content="";
        try{if(c.provider().equals("RULE_BASED")){content="Vui lòng đăng nhập SmartHome AI để xem thông tin và liên hệ quản lý khi cần hỗ trợ. Đây là gợi ý theo mẫu quy tắc, không phải kết quả từ mô hình AI.";state="CONFIGURED";code="RULE_BASED_NOT_A_MODEL";}else{String secret=vault.read(owner,"AI","API_KEY");if(secret.isBlank())throw invalid("AI_API_KEY_MISSING");String instructions="Viết tiếng Việt ngắn gọn về vận hành nhà trọ. Chỉ gợi ý nội dung; không xác nhận giao dịch, không thay đổi hợp đồng hoặc hóa đơn. Không suy diễn dữ liệu cá nhân.";Object payload;HttpRequest.Builder builder;
                if(c.provider().equals("OPENAI")){payload=Map.of("model",c.text("model"),"store",false,"max_output_tokens",384,"input",List.of(Map.of("role","developer","content",instructions),Map.of("role","user","content",request.text())));builder=HttpRequest.newBuilder(URI.create("https://api.openai.com/v1/responses")).header("Authorization","Bearer "+secret);}else{payload=Map.of("systemInstruction",Map.of("parts",List.of(Map.of("text",instructions))),"contents",List.of(Map.of("role","user","parts",List.of(Map.of("text",request.text())))),"generationConfig",Map.of("maxOutputTokens",384));builder=HttpRequest.newBuilder(URI.create("https://generativelanguage.googleapis.com/v1beta/models/"+c.text("model")+":generateContent")).header("x-goog-api-key",secret);}
                var response=http.send(builder.timeout(Duration.ofSeconds(15)).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(json.writeValueAsString(payload))).build(),HttpResponse.BodyHandlers.ofString());if(response.statusCode()!=200)throw invalid(response.statusCode()==401||response.statusCode()==403?"AI_AUTH_REJECTED":"AI_PROVIDER_REJECTED");if(response.body().length()>1000000)throw invalid("AI_RESPONSE_TOO_LARGE");var data=json.readTree(response.body());StringBuilder text=new StringBuilder();if(c.provider().equals("OPENAI")){for(var output:data.path("output"))for(var part:output.path("content"))if(part.path("type").asText().equals("output_text"))text.append(part.path("text").asText());}else for(var part:data.path("candidates").path(0).path("content").path("parts"))text.append(part.path("text").asText());if(text.isEmpty())throw invalid("AI_EMPTY_RESULT");content=text.substring(0,Math.min(6000,text.length()));state="CONNECTED";code="AI_GENERATION_COMPLETED";}
        }catch(com.thangit.boardinghouse.common.exception.AuthException rejected){code=rejected.code();}catch(Exception unavailable){code="AI_PROVIDER_UNAVAILABLE";}
        db.sql("UPDATE integration_operations SET status=:status,result_code=:code,finished_at=:at WHERE owner_id=:owner AND kind='AI' AND operation='AI_GENERATE' AND request_key=:key").param("status",state).param("code",code).param("at",LocalDateTime.now(ZoneOffset.UTC)).param("owner",owner).param("key",key).update();return Map.of("status",state,"resultCode",code,"mode",c.provider(),"content",content,"requiresHumanReview",true);
    }
}
